(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.008-t*0.15)*25+Math.cos(y*0.012+t*0.1)*18;
  const w2y = Math.cos(y*0.009+t*0.18)*22+Math.sin(x*0.011-t*0.12)*16;
  const sx = x+w1x+w2x*0.5, sy = y+w1y+w2y*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*55,0.11,2.1,1.3],
    [400+Math.cos(t*0.55+2)*85,210+Math.sin(t*0.75+4)*65,0.055,2.4,0.85],
    [200+Math.sin(t*0.25)*110,200+Math.cos(t*0.45+3)*75,0.095,1.8,1.05],
    [300+Math.cos(t*0.7+1)*95,30+Math.sin(t*0.5+2)*80,0.075,2.2,0.95]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    wS+=Math.sin(d*f*0.4-t*sp*0.3+2.8)*w*0.5;
  }
  const act=aS/7.5,inh=iS/7.5,weav=wS/7.5;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5),sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*2+t*0.9),sp4=Math.sin(dist*0.03+ang*5-t*2.1);
  const spiral=(sp1+sp2)*0.3+(sp3+sp4)*0.15;
  const voronoi=Math.sin(Math.sin(sx*0.08+t*0.2)*4+Math.cos(sy*0.09-t*0.15)*4+t*0.6)*0.3;
  const feed=act+bg*0.3+spiral*0.4+voronoi;
  const kill=inh*0.7-weav*0.3;
  const laplacian=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin((sx-sy)*0.08-t*0.7)*0.4;
  const rd=Math.tanh((feed-kill+laplacian*0.4)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const pulse=0.95+Math.sin(t*0.4)*0.05;
  const micro=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.35-t*1.2)*0.08;
  const blend=rd*0.6+cell*0.2+micro+voronoi*0.15;
  const v=blend*pulse*0.5+0.5;
  const pal=[
    [5,12,48],[10,45,85],[18,90,115],[25,140,130],
    [60,175,120],[140,195,90],[210,190,60],[230,150,50],
    [220,105,55],[195,65,65],[160,40,70],[110,25,65],
    [65,18,58],[30,14,50],[5,12,48]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(rd*Math.PI)*0.2;
  const edge=Math.abs(rd)>0.7?1.15:Math.abs(rd)>0.4?1.05:1.0;
  const glow=Math.max(0,rd-0.5)*0.3;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
